import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();

        int[] right = new int[61];
        int[] left = new int[61];

        for (int i = 0; i < n; i++) {
            int size = sc.nextInt();
            char foot = sc.next().charAt(0);

